contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable {
        require(address(c).balance >= value, "precondition: enough balance");

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(reverted ? (afterBalance == beforeBalance && afterCount == beforeCount) : (afterBalance + value == beforeBalance && afterCount == beforeCount));
    }

    receive() external payable {}
}

